INSERT INTO categories (name, description)
VALUES
  ('Peripherals', 'Keyboards, mice, and other computer peripherals'),
  ('Accessories', 'General shop accessories')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO products (sku, name, category_id, price, quantity, reorder_level)
SELECT 'KB-001', 'Standard Keyboard', c.id, 799.00, 0, 5
FROM categories c
WHERE c.name = 'Peripherals'
ON DUPLICATE KEY UPDATE sku = VALUES(sku);

